import { test, expect } from '@playwright/test';

test.describe('Password Reset Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/forgot-password');
  });

  test('should display confirmation message after successful password reset', async ({ page }) => {
    // Fill in the email field
    await page.getByLabel('Email Address').fill('user@example.com');

    // Click the reset password button
    await page.getByRole('button', { name: /reset password/i }).click();

    // Verify confirmation message is displayed
    const confirmationMessage = page.getByText(/password reset link has been sent/i);
    await expect(confirmationMessage).toBeVisible();

    // Verify the message contains the email address
    await expect(confirmationMessage).toContainText('user@example.com');
  });

  test('should show confirmation message with correct styling', async ({ page }) => {
    // Fill in the email field
    await page.getByLabel('Email Address').fill('test@example.com');

    // Click the reset password button
    await page.getByRole('button', { name: /reset password/i }).click();

    // Wait for and verify the confirmation message appears
    const confirmationMessage = page.getByRole('status');
    await expect(confirmationMessage).toBeVisible();

    // Verify the message has success styling
    await expect(confirmationMessage).toHaveClass(/success|alert-success/);

    // Verify the message is not empty
    await expect(confirmationMessage).toHaveText(/check your email|confirmation link/i);
  });

  test('should display confirmation message after resetting password with valid token', async ({ page }) => {
    // Navigate to reset password page with token
    await page.goto('http://localhost:3000/reset-password?token=valid-token-123');

    // Fill in new password
    await page.getByLabel('New Password').fill('NewSecurePassword123!');

    // Fill in confirm password
    await page.getByLabel('Confirm Password').fill('NewSecurePassword123!');

    // Click the confirm reset button
    await page.getByRole('button', { name: /confirm|reset/i }).click();

    // Verify success confirmation message is displayed
    const successMessage = page.getByText(/password has been successfully reset/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected or can proceed to login
    await expect(page.getByRole('link', { name: /back to login|login here/i })).toBeVisible();
  });
});
